def kth_distinct(arr, k):
    # First count occurrences of each string
    count = {}
    for s in arr:
        if s in count:
            count[s] += 1
        else:
            count[s] = 1

    # Now find the kᵗʰ distinct string in original order
    for s in arr:
        if count[s] == 1:
            k -= 1
            if k == 0:
                return s

    # If there are less than k distinct strings
    return ""
